  const [manualDeliveryInputs, setManualDeliveryInputs] = useState<Record<number, { status: "pending_payment" | "pending_review" | "in_progress" | "completed" | "failed" | "cancelled"; customerStatusNote: string; internalNote: string }>>({});
  const [supportReply, setSupportReply] = useState("");
