  const [promotionDraft, setPromotionDraft] = useState<{ name: string; code: string; discountType: "percentage" | "fixed_amount"; discountAmount: string; status: "draft" | "scheduled" | "active" | "paused" | "archived" }>({ name: "", code: "", discountType: "percentage", discountAmount: "", status: "draft" });
  const [referralDraft, setReferralDraft] = useState<{ percentageReward: string; fixedReward: string; minimumQualifyingOrder: string; maximumReward: string; releaseDays: string; status: "disabled" | "configured" }>({ percentageReward: "0", fixedReward: "0", minimumQualifyingOrder: "0", maximumReward: "", releaseDays: "0", status: "disabled" });
  const [loyaltyDraft, setLoyaltyDraft] = useState<{ pointsPerCurrencyUnit: string; redemptionValuePerPoint: string; expiryDays: string; status: "disabled" | "configured" }>({ pointsPerCurrencyUnit: "0", redemptionValuePerPoint: "0", expiryDays: "", status: "disabled" });
  const [resellerDraft, setResellerDraft] = useState<{ userId: string; tier: "retail" | "reseller" | "vip_reseller" | "enterprise"; discountPercent: string; status: "pending" | "approved" | "suspended" | "rejected" }>({ userId: "", tier: "retail", discountPercent: "0", status: "pending" });
  const [settingDraft, setSettingDraft] = useState<{ settingKey: string; category: "general" | "currency" | "payments" | "email" | "notifications" | "orders" | "security"; value: string }>({ settingKey: "", category: "general", value: "{}" });
  const [notificationDraft, setNotificationDraft] = useState<{ templateKey: string; channel: "in_app" | "email" | "sms" | "whatsapp"; eventType: string; subject: string; body: string; status: "draft" | "active" | "archived" }>({ templateKey: "", channel: "in_app", eventType: "", subject: "", body: "", status: "draft" });
  const [searchQuery, setSearchQuery] = useState("");
  const searchInput = useMemo(() => ({ query: searchQuery.trim() }), [searchQuery]);
  const search = trpc.admin.search.useQuery(searchInput, { enabled: searchQuery.trim().length >= 2 });
